'use client';

import type React from 'react';
import { useTranslations } from 'next-intl';
import { Button } from '@/src/components/ui/button';
import { Loader2, Save } from 'lucide-react';
import { PageHeader } from '@/src/components/enterprise/PageHeader';
import { CustomerPageShell } from '@/src/components/enterprise/CustomerPageShell';
import { SettingsSidebar } from '@/src/components/settings/SettingsSidebar';

type SettingsPageShellProps = {
  children: React.ReactNode;
  onSave?: () => void | Promise<void>;
  isSaving?: boolean;
  showSave?: boolean;
};

export function SettingsPageShell({
  children,
  onSave,
  isSaving = false,
  showSave = false,
}: SettingsPageShellProps) {
  const t = useTranslations('Settings');

  return (
    <CustomerPageShell width="default" className="pb-12">
      <PageHeader
        title={t('title')}
        description={t('subtitle')}
        actions={
          showSave && onSave ? (
            <Button onClick={onSave} disabled={isSaving} size="sm">
              {isSaving ? (
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              ) : (
                <Save className="mr-2 h-4 w-4" />
              )}
              {isSaving ? t('saving') : t('save')}
            </Button>
          ) : undefined
        }
      />

      <div className="grid gap-6 lg:grid-cols-[220px_minmax(0,1fr)]">
        <aside className="lg:sticky lg:top-24 lg:self-start">
          <div className="vs-card-shell hidden p-2 lg:block">
            <SettingsSidebar />
          </div>
          <div className="vs-card-shell overflow-x-auto p-2 lg:hidden">
            <SettingsSidebar className="!flex-row gap-1" />
          </div>
        </aside>
        <div className="min-w-0">{children}</div>
      </div>
    </CustomerPageShell>
  );
}
